def _f_to_c(fahrenheit: float | None) -> float | None:
    """Convert a Fahrenheit value to Celsius, passing through None."""
    if fahrenheit is None:
        return None
    return TemperatureConverter.convert(
        fahrenheit, UnitOfTemperature.FAHRENHEIT, UnitOfTemperature.CELSIUS
    )


def _c_to_f(celsius: float) -> float:
    """Convert a Celsius value to Fahrenheit."""
    return TemperatureConverter.convert(
        celsius, UnitOfTemperature.CELSIUS, UnitOfTemperature.FAHRENHEIT
    )


async def async_setup_entry(
    hass: HomeAssistant,
    config_entry: WaterFurnaceConfigEntry,
    async_add_entities: AddConfigEntryEntitiesCallback,
) -> None:
    """Set up the WaterFurnace climate platform from a config entry."""
    async_add_entities(
        WaterFurnaceClimate(device_data.realtime)
        for device_data in config_entry.runtime_data.values()
    )


